-- The small audio modules as factory modules (#737, step 4 of the audio foundation #713): env, vca, filter, noise, osc, mixer,
-- transpose (deck/modules/<id>/src/*.rs) become catalog documents `module:<id>` marked `factory: true`, exactly as walk, analog and
-- fixture did in 2026-11-05-factory-modules: read-only, a member derives a module of their own from one. Sources only: `files` are
-- the repository's files byte for byte (server tests/Unit/Domain/FactoryModulesTest keeps them equal).
-- The wasm: NOT in this file. Each reads as not compiled (no descriptor / wasm, so it is no kind in GET /api/kinds yet) until an
-- admin presses Compile on it in the creator's Sound workspace (POST /api/modules/compile { factory: "<id>" }). ORDER: the build
-- service must carry this deploy's SDK first (`deck_module::dsp::level`, `dsp::line`, `Smooth::land`) – with an older SDK they do
-- not build.
-- What it touches:
--   catalog_modules: seven rows, INSERT IGNORE – an existing row with one of these ids (a module a creator made under the name) is
--     left as it is, and then that id is not a factory module (the dry run below shows it; tell the owner).
--   entity_versions: the factory content as the published version of `module:<id>` (message = the marker below); a published
--     version of such a key from before becomes a draft (history).
-- Dry run (before): SELECT id, JSON_EXTRACT(data, '$.factory') AS factory FROM catalog_modules WHERE id IN ('env', 'vca', 'filter', 'noise', 'osc', 'mixer', 'transpose');
--   -> expected: no rows. SELECT entity_key, status, COUNT(*) FROM entity_versions WHERE entity_key IN ('module:env', 'module:vca', 'module:filter', 'module:noise', 'module:osc', 'module:mixer', 'module:transpose')
--   GROUP BY entity_key, status; -> expected: no rows (else: published versions that become history).
-- Test (after): SELECT id, JSON_EXTRACT(data, '$.factory'), JSON_LENGTH(data, '$.files') FROM catalog_modules WHERE id IN ('env', 'vca', 'filter', 'noise', 'osc', 'mixer', 'transpose');
--   -> seven rows, each true 1; SELECT entity_key FROM entity_versions WHERE status = 'published' AND message = 'factory module (migration 2026-11-21-factory-audio-modules)';
--   -> seven rows.
-- Plan's row counts on a database without them: 7 . 0 . 7. MariaDB 10.11, idempotent: a second run changes nothing (INSERT IGNORE;
-- the published marker version exists). Escaping: plain string literals (no NO_BACKSLASH_ESCAPES): `\\` is one backslash of the
-- JSON, `\'` a quote; each row is one line.

INSERT IGNORE INTO `catalog_modules` (`id`, `position`, `data`, `updated_at`, `updated_by`) VALUES
  ('env', 3, '{"id":"env","name":"env","factory":true,"files":{"lib.rs":"//! `env` – an envelope a gate plays: ADSR, AD (a one-shot: attack, then the decay to zero whatever the gate does) or AR\\n//! (attack, held at the top while the gate is up, release). It leaves twice: as audio on `out`, a value a sample, to\\n//! open a vca without steps; and as the control `env`, once a call, for everything slower – a filter\'s cutoff, a light.\\n//! A note on of the `gate` input raises the gate (again from the level it finds), the off of the last note lowers it, a\\n//! reset lowers it. `curve` chooses straight segments or the exponential decay and release of an analog envelope; a\\n//! note keeps the curve it started with. `velocity` is how much a note\'s velocity scales the whole envelope.\\n//!\\n//! Build: `cargo build --release --target wasm32-unknown-unknown -p env-module` (the .wasm in\\n//! `target/wasm32-unknown-unknown/release/env_module.wasm`).\\n// one `#[port(…)]` a port: clippy takes them for duplicates (deck/module/README.md)\\n#![allow(clippy::duplicated_attributes)]\\nuse deck_module::dsp::adsr::{Adsr, Stage, Times};\\nuse deck_module::dsp::line::Line;\\nuse deck_module::{Block, Ctx, Ev, Kind, Module};\\n\\n#[derive(Module)]\\n#[module(name = \\"env\\", doc = \\"an envelope a gate plays: ADSR, AD or AR, as audio and as a control value\\")]\\n#[port(input, event, name = \\"gate\\", names = \\"music.note\\", props = \\"pitch|vel|glide|key\\", capacity = 64, doc = \\"a note on raises the gate, the last note\'s off lowers it\\")]\\n#[port(output, audio, name = \\"out\\", channels = 1, doc = \\"the envelope a sample, 0 … 1: into a vca\'s cv\\")]\\n#[port(output, control, name = \\"env\\", doc = \\"the envelope once a call, 0 … 1: for cutoffs, lights, pictures\\")]\\n#[preset(name = \\"pluck\\", doc = \\"A one-shot that snaps open and falls away in a quarter of a second, louder the harder the note is played.\\", values(mode = 1.0, a = 0.001, d = 0.25, velocity = 60.0))]\\npub struct Env {\\n    #[param(choices = \\"adsr|ad|ar\\", default = 0, doc = \\"adsr: the four stages; ad: attack and decay to zero, the gate\'s length ignored; ar: attack, held, release\\")]\\n    pub mode: f32,\\n    #[param(range = 0.0005..10.0, default = 0.005, curve = log, unit = \\"s\\", doc = \\"attack: the time to the top\\")]\\n    pub a: f32,\\n    #[param(range = 0.001..10.0, default = 0.2, curve = log, unit = \\"s\\", doc = \\"decay: the time from the top to the sustain level (ad: to zero)\\")]\\n    pub d: f32,\\n    #[param(range = 0.0..100.0, default = 70.0, unit = \\"%\\", doc = \\"sustain: the level held while the gate is up (adsr only)\\")]\\n    pub s: f32,\\n    #[param(range = 0.001..20.0, default = 0.3, curve = log, unit = \\"s\\", doc = \\"release: the time to zero after the gate falls\\")]\\n    pub r: f32,\\n    #[param(choices = \\"lin|exp\\", default = 1, doc = \\"lin: straight segments; exp: decay and release fall fast first, like a capacitor\\")]\\n    pub curve: f32,\\n    #[param(range = 0.0..100.0, default = 0.0, unit = \\"%\\", doc = \\"how much the note\'s velocity scales the envelope: 0 = always full\\")]\\n    pub velocity: f32,\\n    bent: Adsr,\\n    straight: Line,\\n    /// the curve the sounding note started with\\n    lin: bool,\\n    held: Option<u32>,\\n    scale: f32,\\n    rate: f64,\\n}\\n\\nimpl Env {\\n    fn one_shot(&self) -> bool {\\n        self.mode.round() as i32 == 1\\n    }\\n\\n    /// the stages\' times in this mode\\n    fn times(&self) -> Times {\\n        match self.mode.round() as i32 {\\n            1 => Times { attack: self.a, decay: self.d, sustain: 0.0, release: self.d },\\n            2 => Times { attack: self.a, decay: 0.0, sustain: 1.0, release: self.r },\\n            _ => Times { attack: self.a, decay: self.d, sustain: self.s / 100.0, release: self.r },\\n        }\\n    }\\n\\n    fn gate_off(&mut self, t: &Times) {\\n        self.held = None;\\n        if !self.one_shot() {\\n            self.bent.gate_off(t, self.rate);\\n            self.straight.gate_off(t, self.rate);\\n        }\\n    }\\n\\n    fn event(&mut self, e: &Ev, t: &Times) {\\n        match e.kind() {\\n            Some(Kind::NoteOn) => {\\n                let (vel, amount) = (e.velocity(), self.velocity / 100.0);\\n                self.scale = 1.0 - amount + amount * if vel.is_finite() { vel.clamp(0.0, 1.0) } else { 1.0 };\\n                self.held = Some(e.id);\\n                // a change of curve takes the next note, which then rises from zero\\n                let lin = self.curve < 0.5;\\n                if lin != self.lin {\\n                    self.lin = lin;\\n                    (self.bent, self.straight) = (Adsr::default(), Line::default());\\n                }\\n                if lin {\\n                    self.straight.gate_on(t, self.rate);\\n                } else {\\n                    self.bent.gate_on(t, self.rate);\\n                }\\n            }\\n            Some(Kind::NoteOff) if self.held == Some(e.id) => self.gate_off(t),\\n            Some(Kind::Reset) => self.gate_off(t),\\n            _ => {}\\n        }\\n    }\\n\\n    fn idle(&self) -> bool {\\n        if self.lin {\\n            self.straight.idle()\\n        } else {\\n            self.bent.idle()\\n        }\\n    }\\n\\n    /// one sample of the shape the note started with\\n    fn tick(&mut self, t: &Times) -> f32 {\\n        let (level, stage) = if self.lin { (self.straight.tick(t, self.rate), self.straight.stage()) } else { (self.bent.tick(t, self.rate), self.bent.stage()) };\\n        // a one-shot is over at the bottom of its decay: it ends there instead of waiting on a sustain of zero\\n        if stage == Stage::Sustain && self.one_shot() {\\n            self.bent.gate_off(t, self.rate);\\n            self.straight.gate_off(t, self.rate);\\n        }\\n        level * self.scale\\n    }\\n}\\n\\nimpl Module for Env {\\n    fn init(&mut self, ctx: &Ctx) {\\n        self.rate = ctx.rate().max(1.0);\\n        self.scale = 1.0;\\n        self.lin = self.curve < 0.5;\\n    }\\n\\n    fn process(&mut self, block: &mut Block, _: &Ctx) {\\n        let t = self.times();\\n        let events = block.events_in(Self::GATE);\\n        if self.idle() && events.is_empty() {\\n            block.set_silent(Self::OUT);\\n            block.set(Self::ENV, 0.0);\\n            return;\\n        }\\n        let (mut next, mut last) = (0, 0.0);\\n        {\\n            let mut out = block.audio_out(Self::OUT);\\n            for (i, o) in out.chan(0).iter_mut().enumerate() {\\n                while let Some(e) = events.get(next).filter(|e| e.frame as usize <= i) {\\n                    self.event(e, &t);\\n                    next += 1;\\n                }\\n                last = self.tick(&t);\\n                *o = last;\\n            }\\n        }\\n        for e in &events[next.min(events.len())..] {\\n            self.event(e, &t);\\n        }\\n        block.set(Self::ENV, last);\\n    }\\n}\\n"}}', UTC_TIMESTAMP(), 'migration:2026-11-21-factory-audio-modules'),
  ('vca', 4, '{"id":"vca","name":"vca","factory":true,"files":{"lib.rs":"//! `vca` – a gain a signal can play: every channel of `in` times `gain`, and, as far as `amount` says, times what\\n//! arrives at the cv inputs – `cv` as audio (an envelope a sample, a tremolo, another sound) plus `cv_control` (a value a\\n//! call: an LFO, a fader, a level from elsewhere). At `amount` 0 it is a plain gain; at 100 % the cv alone opens it and\\n//! nothing connected means silence, as on a hardware VCA. A cv below zero closes it (no phase flip). `gain`, `amount` and\\n//! the control cv glide over two milliseconds, so a knob or a step from the control rate does not click.\\n//!\\n//! Build: `cargo build --release --target wasm32-unknown-unknown -p vca-module` (the .wasm in\\n//! `target/wasm32-unknown-unknown/release/vca_module.wasm`).\\n// one `#[port(…)]` a port: clippy takes them for duplicates (deck/module/README.md)\\n#![allow(clippy::duplicated_attributes)]\\nuse deck_module::dsp::level;\\nuse deck_module::{Block, Ctx, Module, Smooth, QUANTUM};\\n\\n/// the time `gain`, `amount` and the control cv take to move, seconds\\nconst SLEW: f32 = 0.002;\\n/// this close a glide has arrived (−100 dB)\\nconst ARRIVED: f32 = 1e-5;\\n\\n#[derive(Module)]\\n#[module(name = \\"vca\\", doc = \\"a gain a control signal can play: an envelope, an LFO or another sound opens it\\")]\\n#[port(input, audio, name = \\"in\\", channels = \\"any\\", doc = \\"the signal\\")]\\n#[port(input, audio, name = \\"cv\\", channels = 1, sidechain, doc = \\"what opens the vca, a value a sample (0 … 1): an envelope\'s audio output\\")]\\n#[port(input, control, name = \\"cv_control\\", doc = \\"what opens the vca, a value a call (0 … 1); added to cv\\")]\\n#[port(output, audio, name = \\"out\\", channels = \\"any\\", doc = \\"the signal times the gain\\")]\\n#[preset(name = \\"vca\\", doc = \\"Closed until its cv opens it: an envelope into cv makes a note of a running oscillator.\\", values(amount = 100.0))]\\npub struct Vca {\\n    #[param(range = -60.0..12.0, default = 0.0, unit = \\"dB\\", doc = \\"the gain; at the bottom it is silent\\")]\\n    pub gain: f32,\\n    #[param(range = 0.0..100.0, default = 0.0, unit = \\"%\\", doc = \\"how much the cv plays the gain: 0 = not at all, 100 = the cv alone opens it\\")]\\n    pub amount: f32,\\n    amp: Smooth,\\n    depth: Smooth,\\n    control: Smooth,\\n    slew: f32,\\n}\\n\\nimpl Module for Vca {\\n    fn init(&mut self, ctx: &Ctx) {\\n        self.slew = Smooth::coef(SLEW, 1.0 / ctx.rate() as f32);\\n        self.amp.jump(level::gain(self.gain));\\n        self.depth.jump(self.amount / 100.0);\\n    }\\n\\n    fn process(&mut self, block: &mut Block, _: &Ctx) {\\n        self.amp.to(level::gain(self.gain));\\n        self.depth.to(self.amount / 100.0);\\n        self.control.to(block.control_in(Self::CV_CONTROL));\\n        for s in [&mut self.amp, &mut self.depth, &mut self.control] {\\n            s.land(ARRIVED);\\n        }\\n        let n = block.frames();\\n        let cv = block.audio_in(Self::CV).chan(0);\\n        let mut factor = [0.0f32; QUANTUM];\\n        for (f, cv) in factor[..n].iter_mut().zip(cv) {\\n            let depth = self.depth.step(self.slew);\\n            let open = (cv + self.control.step(self.slew)).max(0.0);\\n            *f = self.amp.step(self.slew) * (1.0 - depth + depth * open);\\n        }\\n        let inp = block.audio_in(Self::IN);\\n        if block.in_silent(Self::IN) {\\n            block.set_silent(Self::OUT);\\n            return;\\n        }\\n        let mut out = block.audio_out(Self::OUT);\\n        for c in 0..out.ch() {\\n            // a mono signal goes to every channel\\n            let src = inp.chan(if inp.ch() == 1 { 0 } else { c });\\n            for ((o, x), f) in out.chan(c).iter_mut().zip(src).zip(&factor) {\\n                *o = x * f;\\n            }\\n        }\\n    }\\n}\\n"}}', UTC_TIMESTAMP(), 'migration:2026-11-21-factory-audio-modules'),
  ('filter', 5, '{"id":"filter","name":"filter","factory":true,"files":{"lib.rs":"//! `filter` – the SDK\'s state-variable filter on every channel of `in`: low-pass with 12 or 24 dB an octave (two\\n//! filters in a row, the resonance on the second), band-pass, high-pass or notch, with a drive stage in front. The\\n//! cutoff is the knob, moved in octaves by the `cutoff_mod` control input (an envelope, an LFO) and, as far as `key`\\n//! says, by the last note of the `notes` input: at 100 % it follows the keyboard, neutral at middle C.\\n//!\\n//! The cutoff and the resonance glide and the coefficients are recomputed every sixteen samples of the module\'s own\\n//! clock, so a sweep has no steps and a render does not depend on how the host cuts the blocks.\\n//!\\n//! Build: `cargo build --release --target wasm32-unknown-unknown -p filter-module` (the .wasm in\\n//! `target/wasm32-unknown-unknown/release/filter_module.wasm`).\\n// one `#[port(…)]` a port: clippy takes them for duplicates (deck/module/README.md)\\n#![allow(clippy::duplicated_attributes)]\\nuse deck_module::dsp::arith::{exp2, log2, C4};\\nuse deck_module::dsp::svf::{self, Coef, Mode, Svf};\\nuse deck_module::{Block, Ctx, Ev, Kind, Module, Smooth};\\n\\n/// the channels a cable can carry\\nconst CHANNELS: usize = 32;\\n/// samples between two coefficient updates\\nconst CTRL: usize = 16;\\n/// the time the cutoff and the resonance take to arrive, seconds\\nconst SLEW: f32 = 0.005;\\n\\n#[derive(Module)]\\n#[module(name = \\"filter\\", doc = \\"a state-variable filter: low-pass 12 / 24 dB, band-pass, high-pass, notch, with drive and key tracking\\")]\\n#[port(input, audio, name = \\"in\\", channels = \\"any\\", doc = \\"the signal\\")]\\n#[port(input, control, name = \\"cutoff_mod\\", doc = \\"moves the cutoff, in octaves\\")]\\n#[port(input, event, name = \\"notes\\", names = \\"music.note\\", props = \\"pitch|vel|glide|key\\", capacity = 64, doc = \\"the note the cutoff follows (key)\\")]\\n#[port(output, audio, name = \\"out\\", channels = \\"any\\", doc = \\"the filtered signal\\")]\\n#[preset(name = \\"acid\\", doc = \\"A steep, ringing low-pass with some drive that follows the keyboard half-way: sweep cutoff_mod with an envelope.\\", values(mode = 1.0, cutoff = 400.0, res = 75.0, drive = 30.0, key = 50.0))]\\npub struct Filter {\\n    #[param(choices = \\"lp12|lp24|bp|hp|notch\\", default = 0, doc = \\"low-pass 12 or 24 dB an octave, band-pass, high-pass, notch\\")]\\n    pub mode: f32,\\n    #[param(range = 20.0..20000.0, default = 2000.0, curve = log, unit = \\"Hz\\", doc = \\"the cutoff frequency\\")]\\n    pub cutoff: f32,\\n    #[param(range = 0.0..100.0, default = 10.0, unit = \\"%\\", doc = \\"resonance: the peak at the cutoff, close to ringing at the top\\")]\\n    pub res: f32,\\n    #[param(range = 0.0..100.0, default = 0.0, unit = \\"%\\", doc = \\"how hard the signal is pushed into a soft clip before the filter\\")]\\n    pub drive: f32,\\n    #[param(range = 0.0..100.0, default = 0.0, unit = \\"%\\", doc = \\"key tracking: how far the cutoff follows the last note (100 = an octave an octave)\\")]\\n    pub key: f32,\\n    /// two filters a channel: the second only for 24 dB\\n    stages: [[Svf; 2]; CHANNELS],\\n    /// the cutoff as octaves (log2 Hz) and the resonance 0 … 1, gliding\\n    octave: Smooth,\\n    peak: Smooth,\\n    /// the last note\'s distance from middle C in octaves\\n    note: f32,\\n    plain: Coef,\\n    tuned: Coef,\\n    slew: f32,\\n    clock: usize,\\n    rate: f64,\\n}\\n\\nimpl Filter {\\n    fn cutoff_octave(&self, moved: f32) -> f32 {\\n        log2(f64::from(self.cutoff)) as f32 + moved + self.key / 100.0 * self.note\\n    }\\n\\n    fn track(&mut self, e: &Ev) {\\n        if e.kind() == Some(Kind::NoteOn) && e.pitch_hz().is_finite() && e.pitch_hz() > 0.0 {\\n            self.note = log2(f64::from(e.pitch_hz()) / C4) as f32;\\n        }\\n    }\\n\\n    /// the coefficients for the next `CTRL` samples\\n    fn control(&mut self, moved: f32) {\\n        self.octave.to(self.cutoff_octave(moved));\\n        self.peak.to(self.res / 100.0);\\n        let hz = exp2(f64::from(self.octave.step(self.slew)));\\n        self.tuned = Coef::new(hz, self.peak.step(self.slew), self.rate);\\n        self.plain = Coef::new(hz, 0.0, self.rate);\\n    }\\n}\\n\\nimpl Module for Filter {\\n    fn init(&mut self, ctx: &Ctx) {\\n        self.rate = ctx.rate().max(1.0);\\n        self.slew = Smooth::coef(SLEW, CTRL as f32 / self.rate as f32);\\n        self.octave.jump(self.cutoff_octave(0.0));\\n        self.peak.jump(self.res / 100.0);\\n    }\\n\\n    fn process(&mut self, block: &mut Block, _: &Ctx) {\\n        let events = block.events_in(Self::NOTES);\\n        let moved = block.control_in(Self::CUTOFF_MOD);\\n        let (steep, mode) = match self.mode.round() as i32 {\\n            0 => (false, Mode::Lp),\\n            1 => (true, Mode::Lp),\\n            2 => (false, Mode::Bp),\\n            3 => (false, Mode::Hp),\\n            _ => (false, Mode::Notch),\\n        };\\n        let drive = self.drive / 100.0;\\n        let inp = block.audio_in(Self::IN);\\n        let n = block.frames();\\n        let mut out = block.audio_out(Self::OUT);\\n        let (mut i, mut next) = (0, 0);\\n        while i < n {\\n            while let Some(e) = events.get(next).filter(|e| e.frame as usize <= i) {\\n                self.track(e);\\n                next += 1;\\n            }\\n            if self.clock % CTRL == 0 {\\n                self.control(moved);\\n            }\\n            // up to the next update or the next note, whichever is first\\n            let end = n.min(i + CTRL - self.clock % CTRL).min(events.get(next).map_or(n, |e| e.frame as usize));\\n            for c in 0..out.ch().min(CHANNELS) {\\n                // a mono signal goes to every channel\\n                let src = &inp.chan(if inp.ch() == 1 { 0 } else { c })[i..end];\\n                let [first, second] = &mut self.stages[c];\\n                for (o, x) in out.chan(c)[i..end].iter_mut().zip(src) {\\n                    let x = svf::drive(*x, drive);\\n                    *o = if steep { second.tick(&self.tuned, mode, first.tick(&self.plain, mode, x)) } else { first.tick(&self.tuned, mode, x) };\\n                }\\n            }\\n            self.clock = self.clock.wrapping_add(end - i);\\n            i = end;\\n        }\\n        for e in &events[next.min(events.len())..] {\\n            self.track(e);\\n        }\\n    }\\n}\\n"}}', UTC_TIMESTAMP(), 'migration:2026-11-21-factory-audio-modules'),
  ('noise', 6, '{"id":"noise","name":"noise","factory":true,"files":{"lib.rs":"//! `noise` – seeded noise on one channel: white, or pink (−3 dB an octave). `free` it runs all the time and something\\n//! after it shapes it (an envelope into a vca, a filter); `gated` it is silent until a note on of the `gate` input opens\\n//! it at the note\'s velocity, and that note\'s off closes it – the last note wins, a reset closes. The level and the gate\\n//! move over two milliseconds, so neither clicks. The same seed is the same noise on every deck.\\n//!\\n//! Build: `cargo build --release --target wasm32-unknown-unknown -p noise-module` (the .wasm in\\n//! `target/wasm32-unknown-unknown/release/noise_module.wasm`).\\n// one `#[port(…)]` a port: clippy takes them for duplicates (deck/module/README.md)\\n#![allow(clippy::duplicated_attributes)]\\nuse deck_module::dsp::level;\\nuse deck_module::dsp::noise::{Pink, White};\\nuse deck_module::{Block, Ctx, Ev, Kind, Module, Smooth};\\n\\n/// the time the level and the gate take to move, seconds\\nconst SLEW: f32 = 0.002;\\n/// this close a glide has arrived (−100 dB)\\nconst ARRIVED: f32 = 1e-5;\\n\\n#[derive(Module)]\\n#[module(name = \\"noise\\", doc = \\"seeded white or pink noise, free-running or opened by a gate\\")]\\n#[port(input, event, name = \\"gate\\", names = \\"music.note\\", props = \\"pitch|vel|glide|key\\", capacity = 64, doc = \\"gated: a note on opens the noise at its velocity, its note off closes it\\")]\\n#[port(output, audio, name = \\"out\\", channels = 1, doc = \\"the noise\\")]\\n#[preset(name = \\"hat\\", doc = \\"White noise that sounds only while a gate is open: the source of a hi-hat in front of a filter.\\", values(mode = 1.0, level = -6.0))]\\npub struct Noise {\\n    #[param(choices = \\"white|pink\\", default = 0, doc = \\"white: every frequency alike; pink: 3 dB less an octave up\\")]\\n    pub color: f32,\\n    #[param(range = -60.0..12.0, default = -12.0, unit = \\"dB\\", doc = \\"the level; at the bottom it is silent\\")]\\n    pub level: f32,\\n    #[param(choices = \\"free|gated\\", default = 0, doc = \\"free: it always sounds; gated: only while a note of the gate input is held\\")]\\n    pub mode: f32,\\n    white: White,\\n    pink: Option<Pink>,\\n    amp: Smooth,\\n    open: Smooth,\\n    /// the held note and its velocity\\n    held: Option<(u32, f32)>,\\n    slew: f32,\\n}\\n\\nimpl Noise {\\n    fn gated(&self) -> bool {\\n        self.mode >= 0.5\\n    }\\n\\n    /// how far the gate is open now\\n    fn gate(&self) -> f32 {\\n        match (self.gated(), self.held) {\\n            (false, _) => 1.0,\\n            (true, Some((_, vel))) => vel,\\n            (true, None) => 0.0,\\n        }\\n    }\\n\\n    fn event(&mut self, e: &Ev) {\\n        match e.kind() {\\n            Some(Kind::NoteOn) => {\\n                let vel = e.velocity();\\n                self.held = Some((e.id, if vel.is_finite() { vel.clamp(0.0, 1.0) } else { 1.0 }));\\n            }\\n            Some(Kind::NoteOff) if self.held.is_some_and(|(id, _)| id == e.id) => self.held = None,\\n            Some(Kind::Reset) => self.held = None,\\n            _ => {}\\n        }\\n    }\\n}\\n\\nimpl Module for Noise {\\n    fn init(&mut self, ctx: &Ctx) {\\n        self.white = White::new(ctx.seed());\\n        self.pink = Some(Pink::new(ctx.seed()));\\n        self.slew = Smooth::coef(SLEW, 1.0 / ctx.rate() as f32);\\n        self.amp.jump(level::gain(self.level));\\n        self.open.jump(self.gate());\\n    }\\n\\n    fn process(&mut self, block: &mut Block, _: &Ctx) {\\n        let events = block.events_in(Self::GATE);\\n        self.amp.to(level::gain(self.level));\\n        self.amp.land(ARRIVED);\\n        self.open.land(ARRIVED);\\n        let closed = self.gated() && self.held.is_none() && self.open.value() == 0.0;\\n        if closed && events.is_empty() {\\n            self.amp.jump(self.amp.target());\\n            block.set_silent(Self::OUT);\\n            return;\\n        }\\n        let pink = self.color >= 0.5;\\n        let mut next = 0;\\n        let mut out = block.audio_out(Self::OUT);\\n        for (i, o) in out.chan(0).iter_mut().enumerate() {\\n            while let Some(e) = events.get(next).filter(|e| e.frame as usize <= i) {\\n                self.event(e);\\n                next += 1;\\n            }\\n            self.open.to(self.gate());\\n            let x = match self.pink.as_mut().filter(|_| pink) {\\n                Some(p) => p.sample(),\\n                None => self.white.sample(),\\n            };\\n            *o = x * self.amp.step(self.slew) * self.open.step(self.slew);\\n        }\\n        for e in &events[next.min(events.len())..] {\\n            self.event(e);\\n        }\\n    }\\n}\\n"}}', UTC_TIMESTAMP(), 'migration:2026-11-21-factory-audio-modules'),
  ('osc', 7, '{"id":"osc","name":"osc","factory":true,"files":{"lib.rs":"//! `osc` – one oscillator as a building block: saw, pulse, triangle or sine (the SDK\'s PolyBLEP oscillator), always\\n//! running; what makes a note of it is a vca behind it. Its pitch is the last note\'s of the `notes` input (middle C\\n//! before the first), moved by `semi` and `fine`, by a bend of that note, and by the `pitch` control input in\\n//! semitones (an LFO for vibrato, a sequencer\'s lane); `fm` is audio that swings the frequency around it, linear: +1\\n//! doubles it, −1 stops it. `voices` stacks up to seven oscillators on the one pitch, spread evenly over ±`detune`\\n//! cents (the supersaw), levelled so more voices are not louder.\\n//!\\n//! The pitch is recomputed every sixteen samples of the module\'s own clock and at every note, so a render does not\\n//! depend on how the host cuts the blocks.\\n//!\\n//! Build: `cargo build --release --target wasm32-unknown-unknown -p osc-module` (the .wasm in\\n//! `target/wasm32-unknown-unknown/release/osc_module.wasm`).\\n// one `#[port(…)]` a port: clippy takes them for duplicates (deck/module/README.md)\\n#![allow(clippy::duplicated_attributes)]\\nuse deck_module::dsp::arith::{exp2, C4};\\nuse deck_module::dsp::osc::{Osc as Unit, Wave};\\nuse deck_module::{Block, Ctx, Ev, Expr, Kind, Module, Smooth};\\n\\npub const VOICES: usize = 7;\\n/// samples between two pitch updates\\nconst CTRL: u32 = 16;\\n/// the time the `pitch` input and the knobs take to arrive, seconds\\nconst SLEW: f32 = 0.005;\\n/// 1 / √n: n voices as loud as one\\nconst LEVEL: [f32; VOICES] = [1.0, 0.707_106_77, 0.577_350_26, 0.5, 0.447_213_6, 0.408_248_3, 0.377_964_47];\\n\\n#[derive(Module)]\\n#[module(name = \\"osc\\", doc = \\"one oscillator: saw, pulse, triangle or sine, up to seven detuned voices, pitched by notes\\")]\\n#[port(input, event, name = \\"notes\\", names = \\"music.note\\", props = \\"pitch|vel|glide|key\\", capacity = 64, doc = \\"a note on sets the pitch; a bend of that note moves it\\")]\\n#[port(input, audio, name = \\"fm\\", channels = 1, sidechain, doc = \\"frequency modulation, linear: +1 doubles the frequency, −1 stops it\\")]\\n#[port(input, control, name = \\"pitch\\", doc = \\"added to the pitch, in semitones\\")]\\n#[port(output, audio, name = \\"out\\", channels = 1, doc = \\"the wave, −1 … 1\\")]\\n#[preset(name = \\"supersaw\\", doc = \\"Seven saws a quarter of a semitone wide: the wide, beating lead.\\", values(wave = 0.0, voices = 7.0, detune = 25.0))]\\npub struct Osc {\\n    #[param(choices = \\"saw|pulse|triangle|sine\\", default = 0, doc = \\"the waveform\\")]\\n    pub wave: f32,\\n    #[param(range = -48.0..48.0, default = 0.0, unit = \\"st\\", doc = \\"pitch offset in semitones\\")]\\n    pub semi: f32,\\n    #[param(range = -100.0..100.0, default = 0.0, unit = \\"cent\\", doc = \\"fine tuning\\")]\\n    pub fine: f32,\\n    #[param(range = 5.0..95.0, default = 50.0, unit = \\"%\\", doc = \\"pulse width (the pulse wave only)\\")]\\n    pub pw: f32,\\n    #[param(range = 0.0..100.0, default = 0.0, unit = \\"cent\\", doc = \\"how far the outermost voices sit from the pitch\\")]\\n    pub detune: f32,\\n    #[param(range = 1.0..7.0, default = 1.0, doc = \\"how many oscillators play the pitch\\")]\\n    pub voices: f32,\\n    units: [Unit; VOICES],\\n    /// cycles a sample, per voice\\n    dt: [f64; VOICES],\\n    /// the note\'s pitch, the note that set it and its bend in semitones\\n    hz: f64,\\n    note: Option<u32>,\\n    bend: f32,\\n    /// the offset in semitones: `semi`, `fine`, the bend and the `pitch` input\\n    offset: Smooth,\\n    slew: f32,\\n    clock: u32,\\n    rate: f64,\\n}\\n\\nimpl Osc {\\n    pub fn count(&self) -> usize {\\n        (self.voices.round() as usize).clamp(1, VOICES)\\n    }\\n\\n    fn event(&mut self, e: &Ev) {\\n        match e.kind() {\\n            Some(Kind::NoteOn) => {\\n                let hz = e.pitch_hz();\\n                if hz.is_finite() && hz > 0.0 {\\n                    (self.hz, self.note, self.bend) = (f64::from(hz), Some(e.id), 0.0);\\n                    // the note\'s pitch is there at its frame\\n                    self.clock = 0;\\n                }\\n            }\\n            Some(Kind::NoteExpr) if self.note == Some(e.id) => {\\n                if let Some((Expr::Bend, semis)) = e.expr().filter(|(_, v)| v.is_finite()) {\\n                    self.bend = semis;\\n                }\\n            }\\n            _ => {}\\n        }\\n    }\\n\\n    fn pitch(&mut self, input: f32) {\\n        self.offset.to(self.semi + self.fine / 100.0 + self.bend + input);\\n        let st = f64::from(self.offset.step(self.slew));\\n        let n = self.count();\\n        for (k, dt) in self.dt[..n].iter_mut().enumerate() {\\n            let spread = if n == 1 { 0.0 } else { 2.0 * k as f64 / (n - 1) as f64 - 1.0 };\\n            *dt = self.hz * exp2((st + spread * f64::from(self.detune) / 100.0) / 12.0) / self.rate;\\n        }\\n    }\\n}\\n\\nimpl Module for Osc {\\n    fn init(&mut self, ctx: &Ctx) {\\n        self.rate = ctx.rate().max(1.0);\\n        self.hz = C4;\\n        self.slew = Smooth::coef(SLEW, CTRL as f32 / self.rate as f32);\\n        self.offset.jump(self.semi + self.fine / 100.0);\\n    }\\n\\n    fn process(&mut self, block: &mut Block, _: &Ctx) {\\n        let events = block.events_in(Self::NOTES);\\n        let input = block.control_in(Self::PITCH);\\n        let fm = block.audio_in(Self::FM).chan(0);\\n        let (wave, pw) = (Wave::from_param(self.wave), f64::from(self.pw) / 100.0);\\n        let mut next = 0;\\n        let mut out = block.audio_out(Self::OUT);\\n        for (i, o) in out.chan(0).iter_mut().enumerate() {\\n            while let Some(e) = events.get(next).filter(|e| e.frame as usize <= i) {\\n                self.event(e);\\n                next += 1;\\n            }\\n            if self.clock % CTRL == 0 {\\n                self.pitch(input);\\n            }\\n            self.clock = self.clock.wrapping_add(1);\\n            let n = self.count();\\n            let swing = 1.0 + f64::from(fm[i]);\\n            let mut sum = 0.0;\\n            for (unit, dt) in self.units[..n].iter_mut().zip(&self.dt) {\\n                sum += unit.tick(wave, dt * swing, pw, None).value;\\n            }\\n            *o = sum * LEVEL[n - 1];\\n        }\\n        for e in &events[next.min(events.len())..] {\\n            self.event(e);\\n        }\\n    }\\n}\\n"}}', UTC_TIMESTAMP(), 'migration:2026-11-21-factory-audio-modules'),
  ('mixer', 8, '{"id":"mixer","name":"mixer","factory":true,"files":{"lib.rs":"//! `mixer` – a rig\'s own mixer: eight stereo inputs summed into `out`, each with a level, a balance and a mute, and a\\n//! second sum, `send`, that takes of every input what its send level says – after the input\'s level and mute, before\\n//! its balance – for one shared effect (a reverb, a delay) whose return comes back into another input. `master` is the\\n//! level of `out` alone. The balance leaves the centre as it is and turns the other side down, so a stereo input keeps\\n//! its level in the middle; a mono cable sounds on both sides. Every level glides over two milliseconds. (The engine\'s\\n//! `mixer` kind stays the scene\'s; this one sits inside a rig.)\\n//!\\n//! Build: `cargo build --release --target wasm32-unknown-unknown -p mixer-module` (the .wasm in\\n//! `target/wasm32-unknown-unknown/release/mixer_module.wasm`).\\n// one `#[port(…)]` a port: clippy takes them for duplicates (deck/module/README.md)\\n#![allow(clippy::duplicated_attributes)]\\nuse deck_module::dsp::level;\\nuse deck_module::{Block, Ctx, Dirty, Module, Smooth, QUANTUM};\\n\\npub const INPUTS: usize = 8;\\n/// the time a level takes to move, seconds\\nconst SLEW: f32 = 0.002;\\n/// this close a glide has arrived (−100 dB)\\nconst ARRIVED: f32 = 1e-5;\\n\\n#[derive(Module)]\\n#[module(name = \\"mixer\\", doc = \\"eight stereo inputs into one stereo sum and one send, each with level, balance, send and mute\\")]\\n#[port(input, audio, name = \\"in1\\", channels = 2, doc = \\"input 1\\")]\\n#[port(input, audio, name = \\"in2\\", channels = 2, doc = \\"input 2\\")]\\n#[port(input, audio, name = \\"in3\\", channels = 2, doc = \\"input 3\\")]\\n#[port(input, audio, name = \\"in4\\", channels = 2, doc = \\"input 4\\")]\\n#[port(input, audio, name = \\"in5\\", channels = 2, doc = \\"input 5\\")]\\n#[port(input, audio, name = \\"in6\\", channels = 2, doc = \\"input 6\\")]\\n#[port(input, audio, name = \\"in7\\", channels = 2, doc = \\"input 7\\")]\\n#[port(input, audio, name = \\"in8\\", channels = 2, doc = \\"input 8\\")]\\n#[port(output, audio, name = \\"out\\", channels = 2, doc = \\"the sum of the inputs times master\\")]\\n#[port(output, audio, name = \\"send\\", channels = 2, doc = \\"the sum of what the inputs send: into one shared effect\\")]\\n#[preset(name = \\"pair\\", doc = \\"Inputs 1 and 2 as a wide pair, both feeding the send a little.\\", values(pan1 = -0.6, pan2 = 0.6, send1 = -12.0, send2 = -12.0))]\\npub struct Mixer {\\n    #[param(range = -60.0..12.0, default = 0.0, unit = \\"dB\\", doc = \\"input 1: its level; at the bottom it is silent\\")]\\n    pub gain1: f32,\\n    #[param(range = -60.0..12.0, default = 0.0, unit = \\"dB\\", doc = \\"input 2: its level; at the bottom it is silent\\")]\\n    pub gain2: f32,\\n    #[param(range = -60.0..12.0, default = 0.0, unit = \\"dB\\", doc = \\"input 3: its level; at the bottom it is silent\\")]\\n    pub gain3: f32,\\n    #[param(range = -60.0..12.0, default = 0.0, unit = \\"dB\\", doc = \\"input 4: its level; at the bottom it is silent\\")]\\n    pub gain4: f32,\\n    #[param(range = -60.0..12.0, default = 0.0, unit = \\"dB\\", doc = \\"input 5: its level; at the bottom it is silent\\")]\\n    pub gain5: f32,\\n    #[param(range = -60.0..12.0, default = 0.0, unit = \\"dB\\", doc = \\"input 6: its level; at the bottom it is silent\\")]\\n    pub gain6: f32,\\n    #[param(range = -60.0..12.0, default = 0.0, unit = \\"dB\\", doc = \\"input 7: its level; at the bottom it is silent\\")]\\n    pub gain7: f32,\\n    #[param(range = -60.0..12.0, default = 0.0, unit = \\"dB\\", doc = \\"input 8: its level; at the bottom it is silent\\")]\\n    pub gain8: f32,\\n    #[param(range = -1.0..1.0, default = 0.0, doc = \\"input 1: its balance, −1 left … 1 right\\")]\\n    pub pan1: f32,\\n    #[param(range = -1.0..1.0, default = 0.0, doc = \\"input 2: its balance, −1 left … 1 right\\")]\\n    pub pan2: f32,\\n    #[param(range = -1.0..1.0, default = 0.0, doc = \\"input 3: its balance, −1 left … 1 right\\")]\\n    pub pan3: f32,\\n    #[param(range = -1.0..1.0, default = 0.0, doc = \\"input 4: its balance, −1 left … 1 right\\")]\\n    pub pan4: f32,\\n    #[param(range = -1.0..1.0, default = 0.0, doc = \\"input 5: its balance, −1 left … 1 right\\")]\\n    pub pan5: f32,\\n    #[param(range = -1.0..1.0, default = 0.0, doc = \\"input 6: its balance, −1 left … 1 right\\")]\\n    pub pan6: f32,\\n    #[param(range = -1.0..1.0, default = 0.0, doc = \\"input 7: its balance, −1 left … 1 right\\")]\\n    pub pan7: f32,\\n    #[param(range = -1.0..1.0, default = 0.0, doc = \\"input 8: its balance, −1 left … 1 right\\")]\\n    pub pan8: f32,\\n    #[param(range = -60.0..12.0, default = -60.0, unit = \\"dB\\", doc = \\"input 1: how much of it goes to the send output, after its level; at the bottom nothing\\")]\\n    pub send1: f32,\\n    #[param(range = -60.0..12.0, default = -60.0, unit = \\"dB\\", doc = \\"input 2: how much of it goes to the send output, after its level; at the bottom nothing\\")]\\n    pub send2: f32,\\n    #[param(range = -60.0..12.0, default = -60.0, unit = \\"dB\\", doc = \\"input 3: how much of it goes to the send output, after its level; at the bottom nothing\\")]\\n    pub send3: f32,\\n    #[param(range = -60.0..12.0, default = -60.0, unit = \\"dB\\", doc = \\"input 4: how much of it goes to the send output, after its level; at the bottom nothing\\")]\\n    pub send4: f32,\\n    #[param(range = -60.0..12.0, default = -60.0, unit = \\"dB\\", doc = \\"input 5: how much of it goes to the send output, after its level; at the bottom nothing\\")]\\n    pub send5: f32,\\n    #[param(range = -60.0..12.0, default = -60.0, unit = \\"dB\\", doc = \\"input 6: how much of it goes to the send output, after its level; at the bottom nothing\\")]\\n    pub send6: f32,\\n    #[param(range = -60.0..12.0, default = -60.0, unit = \\"dB\\", doc = \\"input 7: how much of it goes to the send output, after its level; at the bottom nothing\\")]\\n    pub send7: f32,\\n    #[param(range = -60.0..12.0, default = -60.0, unit = \\"dB\\", doc = \\"input 8: how much of it goes to the send output, after its level; at the bottom nothing\\")]\\n    pub send8: f32,\\n    #[param(choices = \\"off|on\\", default = 0, doc = \\"input 1: muted, in out and send\\")]\\n    pub mute1: f32,\\n    #[param(choices = \\"off|on\\", default = 0, doc = \\"input 2: muted, in out and send\\")]\\n    pub mute2: f32,\\n    #[param(choices = \\"off|on\\", default = 0, doc = \\"input 3: muted, in out and send\\")]\\n    pub mute3: f32,\\n    #[param(choices = \\"off|on\\", default = 0, doc = \\"input 4: muted, in out and send\\")]\\n    pub mute4: f32,\\n    #[param(choices = \\"off|on\\", default = 0, doc = \\"input 5: muted, in out and send\\")]\\n    pub mute5: f32,\\n    #[param(choices = \\"off|on\\", default = 0, doc = \\"input 6: muted, in out and send\\")]\\n    pub mute6: f32,\\n    #[param(choices = \\"off|on\\", default = 0, doc = \\"input 7: muted, in out and send\\")]\\n    pub mute7: f32,\\n    #[param(choices = \\"off|on\\", default = 0, doc = \\"input 8: muted, in out and send\\")]\\n    pub mute8: f32,\\n    #[param(range = -60.0..12.0, default = 0.0, unit = \\"dB\\", doc = \\"the level of out; at the bottom it is silent\\")]\\n    pub master: f32,\\n    /// per input: its factors into out\'s left and right and into send, gliding\\n    strips: [[Smooth; 3]; INPUTS],\\n    total: Smooth,\\n    slew: f32,\\n}\\n\\nimpl Mixer {\\n    /// where every factor heads, from the parameters\\n    fn aim(&mut self) {\\n        let gains = [self.gain1, self.gain2, self.gain3, self.gain4, self.gain5, self.gain6, self.gain7, self.gain8];\\n        let pans = [self.pan1, self.pan2, self.pan3, self.pan4, self.pan5, self.pan6, self.pan7, self.pan8];\\n        let sends = [self.send1, self.send2, self.send3, self.send4, self.send5, self.send6, self.send7, self.send8];\\n        let mutes = [self.mute1, self.mute2, self.mute3, self.mute4, self.mute5, self.mute6, self.mute7, self.mute8];\\n        for (k, [left, right, send]) in self.strips.iter_mut().enumerate() {\\n            let gain = if mutes[k] >= 0.5 { 0.0 } else { level::gain(gains[k]) };\\n            left.to(gain * (1.0 - pans[k]).min(1.0));\\n            right.to(gain * (1.0 + pans[k]).min(1.0));\\n            send.to(gain * level::gain(sends[k]));\\n        }\\n        self.total.to(level::gain(self.master));\\n    }\\n}\\n\\nimpl Module for Mixer {\\n    fn init(&mut self, ctx: &Ctx) {\\n        self.slew = Smooth::coef(SLEW, 1.0 / ctx.rate() as f32);\\n        self.aim();\\n        for s in self.strips.iter_mut().flatten().chain([&mut self.total]) {\\n            s.jump(s.target());\\n        }\\n    }\\n\\n    fn params_changed(&mut self, _: Dirty) {\\n        self.aim();\\n    }\\n\\n    fn process(&mut self, block: &mut Block, _: &Ctx) {\\n        let n = block.frames();\\n        for s in self.strips.iter_mut().flatten().chain([&mut self.total]) {\\n            s.land(ARRIVED);\\n        }\\n        // out left, out right, send left, send right\\n        let mut sums = [[0.0f32; QUANTUM]; 4];\\n        let mut sounding = false;\\n        for (k, [left, right, send]) in self.strips.iter_mut().enumerate() {\\n            if block.in_silent(k) {\\n                // nothing to hear: the levels are where they head when a signal comes\\n                for s in [left, right, send] {\\n                    s.jump(s.target());\\n                }\\n                continue;\\n            }\\n            sounding = true;\\n            let (l, r) = block.audio_in(k).stereo();\\n            for i in 0..n {\\n                let (a, b, c) = (left.step(self.slew), right.step(self.slew), send.step(self.slew));\\n                sums[0][i] += l[i] * a;\\n                sums[1][i] += r[i] * b;\\n                sums[2][i] += l[i] * c;\\n                sums[3][i] += r[i] * c;\\n            }\\n        }\\n        if !sounding {\\n            self.total.jump(self.total.target());\\n            block.set_silent(Self::OUT);\\n            block.set_silent(Self::SEND);\\n            return;\\n        }\\n        {\\n            let mut out = block.audio_out(Self::OUT);\\n            let (l, r) = out.stereo();\\n            for i in 0..n.min(l.len()).min(r.len()) {\\n                let master = self.total.step(self.slew);\\n                l[i] = sums[0][i] * master;\\n                r[i] = sums[1][i] * master;\\n            }\\n        }\\n        let mut send = block.audio_out(Self::SEND);\\n        let (l, r) = send.stereo();\\n        l.copy_from_slice(&sums[2][..l.len()]);\\n        r.copy_from_slice(&sums[3][..r.len()]);\\n    }\\n}\\n"}}', UTC_TIMESTAMP(), 'migration:2026-11-21-factory-audio-modules'),
  ('transpose', 9, '{"id":"transpose","name":"transpose","factory":true,"files":{"lib.rs":"//! `transpose` – notes in, the same notes out, moved in pitch: a note on leaves with its Hz and its key shifted by\\n//! `semi` semitones and `fine` cents, at its frame and under its id; note offs, bends and a reset pass as they are, so\\n//! a note ends on the voice that started it whatever the knobs did in between. No state.\\n//!\\n//! Build: `cargo build --release --target wasm32-unknown-unknown -p transpose-module` (the .wasm in\\n//! `target/wasm32-unknown-unknown/release/transpose_module.wasm`).\\n// one `#[port(…)]` a port: clippy takes them for duplicates (deck/module/README.md)\\n#![allow(clippy::duplicated_attributes)]\\nuse deck_module::dsp::arith::exp2;\\nuse deck_module::{Block, Ctx, Kind, Module};\\n\\n#[derive(Module)]\\n#[module(name = \\"transpose\\", doc = \\"notes moved in pitch by semitones and cents\\")]\\n#[port(input, event, name = \\"notes\\", names = \\"music.note\\", props = \\"pitch|vel|glide|key\\", capacity = 64, doc = \\"the notes to move\\")]\\n#[port(output, event, name = \\"out\\", names = \\"music.note\\", props = \\"pitch|vel|glide|key\\", capacity = 64, doc = \\"the same notes, their pitch moved\\")]\\n#[preset(name = \\"octave up\\", doc = \\"Every note an octave higher.\\", values(semi = 12.0))]\\npub struct Transpose {\\n    #[param(range = -48.0..48.0, default = 0.0, unit = \\"st\\", doc = \\"how far every note moves, in semitones\\")]\\n    pub semi: f32,\\n    #[param(range = -100.0..100.0, default = 0.0, unit = \\"cent\\", doc = \\"a fine shift on top, in cents\\")]\\n    pub fine: f32,\\n}\\n\\nimpl Transpose {\\n    /// the shift in semitones\\n    pub fn semitones(&self) -> f64 {\\n        f64::from(self.semi) + f64::from(self.fine) / 100.0\\n    }\\n}\\n\\nimpl Module for Transpose {\\n    fn process(&mut self, block: &mut Block, _: &Ctx) {\\n        let st = self.semitones();\\n        let ratio = exp2(st / 12.0);\\n        for e in block.events_in(Self::NOTES) {\\n            let mut moved = *e;\\n            if e.kind() == Some(Kind::NoteOn) {\\n                // an absent Hz or key stays absent (NaN): the next event host fills it from the other\\n                moved.v[0] = (f64::from(e.pitch_hz()) * ratio) as f32;\\n                moved.v[3] = (f64::from(e.key()) + st) as f32;\\n            }\\n            block.emit(Self::OUT, moved);\\n        }\\n    }\\n}\\n"}}', UTC_TIMESTAMP(), 'migration:2026-11-21-factory-audio-modules');

-- an earlier published version of a factory key becomes history (only where the factory row is ours)
UPDATE `entity_versions` SET `status` = 'draft'
 WHERE `entity_key` IN ('module:env', 'module:vca', 'module:filter', 'module:noise', 'module:osc', 'module:mixer', 'module:transpose') AND `status` = 'published'
   AND COALESCE(`message`, '') <> 'factory module (migration 2026-11-21-factory-audio-modules)'
   AND EXISTS (SELECT 1 FROM `catalog_modules` m WHERE CONCAT('module:', m.`id`) COLLATE utf8mb4_general_ci = `entity_versions`.`entity_key`
               AND JSON_CONTAINS(m.`data`, 'true', '$.factory'));

-- the factory content as the published version (the creator's document)
INSERT INTO `entity_versions` (`entity_key`, `kind`, `toon`, `locale`, `json`, `author`, `created_at`, `status`, `message`)
SELECT CONCAT('module:', m.`id`), 'module', NULL, NULL, m.`data`, NULL, UTC_TIMESTAMP(), 'published', 'factory module (migration 2026-11-21-factory-audio-modules)'
  FROM `catalog_modules` m
 WHERE m.`id` IN ('env', 'vca', 'filter', 'noise', 'osc', 'mixer', 'transpose') AND JSON_CONTAINS(m.`data`, 'true', '$.factory')
   AND NOT EXISTS (SELECT 1 FROM `entity_versions` e WHERE e.`entity_key` = CONCAT('module:', m.`id`) COLLATE utf8mb4_general_ci
                   AND e.`message` = 'factory module (migration 2026-11-21-factory-audio-modules)');
